fn database(layout: Layout) -> Connection {
    let mut conn = Connection::open_in_memory().unwrap();
    schema::prepare(&mut conn, "test", &SystemClock).unwrap();
    if let Layout::Migrated = layout {
        for (table, order) in MIGRATED_COLUMNS {
