            // rooms), and the action fails on it: a 500, where `Membership#room`'s
            // `RecordNotFound` would be a 404.
            let room =
                Room::find_by_id(conn, membership.room_id)?.ok_or_else(|| campfire_db::Error::other("the membership's room is gone"))?;
            Ok((membership, room))
        })
        .await
}

