use crate::models::{Bot, NewUser, PasswordDigest, Role, User};
use crate::tests::{TestDb, id};

#[test]
fn bot_crud_and_queries() {
    let t = TestDb::new();
    let creator_id = id("david");

    // Create user for bot
    let bot_user = t.write(|tx| {
        User::create(
            tx,
            NewUser {
                name: "Deploy Bot".into(),
                password_digest: Some(PasswordDigest::from_string("dummy".into())),
                role: Role::Member,
                ..Default::default()
            },
        )
    });

    // Create bot
    let code = Bot::generate_code();
    let bot = t.write(|tx| Bot::create(tx, bot_user.id, creator_id, &code));
    assert_eq!(bot.user_id, bot_user.id);
    assert_eq!(bot.creator_id, creator_id);
    assert_eq!(bot.code, code);

    // Finders
    let found = t.read(|c| Bot::find(c, bot.id)).unwrap();
    assert_eq!(found, bot);

    let found_by_code = t.read(|c| Bot::find_by_code(c, &code)).unwrap().unwrap();
    assert_eq!(found_by_code, bot);

    let found_by_user = t.read(|c| Bot::find_by_user_id(c, bot_user.id)).unwrap().unwrap();
    assert_eq!(found_by_user, bot);

    let bots = t.read(|c| Bot::for_creator(c, creator_id)).unwrap();
    assert!(bots.iter().any(|b| b.id == bot.id));

    let all = t.read(Bot::all).unwrap();
    assert!(all.iter().any(|b| b.id == bot.id));

    // Destroy
    t.write(|tx| bot.destroy(tx));
    assert!(t.read(|c| Bot::find_by_id(c, bot.id)).unwrap().is_none());
    assert!(t.read(|c| Bot::find_by_code(c, &code)).unwrap().is_none());
}
